            {data:<?= json_encode($finance_document_kind === 'sales' ? 'invoice_number' : 'bill_number') ?>,name:<?= json_encode($finance_document_kind === 'sales' ? 'invoice_number' : 'bill_number') ?>,render:function(v,t){return t==='display'?escapeHtml(v):v;}},
